/* Six MSVC EH unwind-funclet templates. __CxxFrameHandler calls these with EBP = the parent frame;
 * they are __attribute__((naked)) and must not grow a prologue. Generated by tools/gen_eh_funclets.py. */
#ifndef LOM_EH_FUNCLET_H
#define LOM_EH_FUNCLET_H

#define EH_THISCALL_DTOR_JMP_LEA(addr, ebp_off, dtor) \
  __attribute__((naked)) void rb_##addr(void) { \
    __asm__( \
      "leal " #ebp_off "(%ebp), %ecx\n" \
      "jmp *_lom_fl_" #addr "_0\n" \
    ); \
  } \
  __asm__(".data\n.globl _lom_fl_" #addr "_0\n_lom_fl_" #addr "_0: .long " #dtor "\n.text\n");

#define EH_THISCALL_DTOR_JMP_ECX(addr, ebp_off, dtor) \
  __attribute__((naked)) void rb_##addr(void) { \
    __asm__( \
      "movl " #ebp_off "(%ebp), %ecx\n" \
      "jmp *_lom_fl_" #addr "_0\n" \
    ); \
  } \
  __asm__(".data\n.globl _lom_fl_" #addr "_0\n_lom_fl_" #addr "_0: .long " #dtor "\n.text\n");

#define EH_THISCALL_DTOR_JMP_ECX_ADD(addr, ebp_off, add_off, dtor) \
  __attribute__((naked)) void rb_##addr(void) { \
    __asm__( \
      "movl " #ebp_off "(%ebp), %ecx\n" \
      "addl $" #add_off ", %ecx\n" \
      "jmp *_lom_fl_" #addr "_0\n" \
    ); \
  } \
  __asm__(".data\n.globl _lom_fl_" #addr "_0\n_lom_fl_" #addr "_0: .long " #dtor "\n.text\n");

#define EH_CDECL_DTOR_LOCAL(addr, ebp_off, dtor) \
  __attribute__((naked)) void rb_##addr(void) { \
    __asm__( \
      "movl " #ebp_off "(%ebp), %eax\n" \
      "pushl %eax\n" \
      "call *_lom_fl_" #addr "_0\n" \
      "popl %ecx\n" \
      "retl\n" \
    ); \
  } \
  __asm__(".data\n.globl _lom_fl_" #addr "_0\n_lom_fl_" #addr "_0: .long " #dtor "\n.text\n");

#define EH_EHVEC_DTOR_SUBOBJECT(addr, ebp_off, add_off, elem_dtor, count, size, vec_dtor) \
  __attribute__((naked)) void rb_##addr(void) { \
    __asm__( \
      "pushl $" #elem_dtor "\n" \
      "pushl $" #count "\n" \
      "pushl $" #size "\n" \
      "movl " #ebp_off "(%ebp), %eax\n" \
      "addl $" #add_off ", %eax\n" \
      "pushl %eax\n" \
      "call *_lom_fl_" #addr "_0\n" \
      "retl\n" \
    ); \
  } \
  __asm__(".data\n.globl _lom_fl_" #addr "_0\n_lom_fl_" #addr "_0: .long " #vec_dtor "\n.text\n");

#define EH_EHVEC_DTOR_LEA_LOCAL(addr, ebp_off, elem_dtor, count, size, vec_dtor) \
  __attribute__((naked)) void rb_##addr(void) { \
    __asm__( \
      "pushl $" #elem_dtor "\n" \
      "pushl $" #count "\n" \
      "pushl $" #size "\n" \
      "leal " #ebp_off "(%ebp), %eax\n" \
      "pushl %eax\n" \
      "call *_lom_fl_" #addr "_0\n" \
      "retl\n" \
    ); \
  } \
  __asm__(".data\n.globl _lom_fl_" #addr "_0\n_lom_fl_" #addr "_0: .long " #vec_dtor "\n.text\n");

#endif
